script:
// Function to fetch user data and update profile
frappe.call({
    method: "frappe.client.get",
    args: {
        doctype: "User",
        name: frappe.session.user,
    },
    callback: function(r) {
        if (r.message) {
            let fullNameElement = root_element.querySelector("#full_name");
            let emailElement = root_element.querySelector("#email");
            let lastLoginElement = root_element.querySelector("#last_login");
            let imageElement = root_element.querySelector("#user_image");

            // Set the content of the elements
            fullNameElement.textContent = r.message.full_name;
            emailElement.textContent = r.message.email;

            // Format the last login datetime
            let lastLogin = r.message.last_login;
            if (lastLogin) {
                let date = new Date(lastLogin);
                let formattedDate = date.toLocaleString('en-GB', {
                    day: '2-digit',
                    month: 'short',
                    year: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                    second: '2-digit',
                    hour12: false
                }).replace(',', ''); // Remove the comma in the default format
                lastLoginElement.textContent = formattedDate;
            } else {
                lastLoginElement.textContent = "No login record";
            }

            // Set user image or fallback to a generated avatar
            if (r.message.user_image) {
                imageElement.src = r.message.user_image;
            } else {
                // Generate avatar based on user initials
                let initials = r.message.full_name.split(' ')
                                 .map(name => name[0])
                                 .join('')
                                 .toUpperCase();
                let avatarUrl = `https://ui-avatars.com/api/?name=${initials}&background=random&color=fff`;
                imageElement.src = avatarUrl;
            }
        }
    }
});

// Clock function
function showTime() {
    const time = new Date();
    let hour = time.getHours();
    let min = time.getMinutes();
    let sec = time.getSeconds();
    let am_pm = "AM";

    if (hour >= 12) {
        am_pm = "PM";
        if (hour > 12) {
            hour -= 12;
        }
    }

    if (hour === 0) {
        hour = 12;
    }

    hour = hour < 10 ? "0" + hour : hour;
    min = min < 10 ? "0" + min : min;
    sec = sec < 10 ? "0" + sec : sec;

    const currentTime = `${hour}:${min}:${sec} ${am_pm}`;
    root_element.querySelector("#clock").textContent = currentTime; // Using root_element as parent selector
}

setInterval(showTime, 1000); // Update time every second
showTime(); // Initialize clock

style:
/* Container for user profile */
.profile-container {
    margin: auto;
    background-color: #fff;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    font-family: 'Arial', sans-serif;
    overflow: hidden;
}

/* Cover Photo */
.cover-photo img {
    width: 100%;
    height: 120px;
    object-fit: cover;
}

/* Profile Picture */
.profile-img {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #fff;
    margin: -30px 20px 0; /* Adjust margin for left alignment */
    background-color: #fff;
    display: inline-block;
    vertical-align: middle;
}

/* Profile body */
.profile-body {
    padding: 10px 20px;

}

/* Profile info and clock row */
.profile-info-clock {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 -20px;
}

/* Profile details (name, email, last login) */
.profile-details {
    display: flex;
    flex-direction: column;
    text-align: left;
    /*margin-left: -20px; */
}

/* Profile item */
.profile-item {
    margin-bottom: 5px;
}

.profile-item strong {
    color: #333;
    margin-right: 10px;
}

.profile-item span {
    color: #000;
    font-weight: bold;
}

/* Clock */
#clock {
    font-size: 24px;
    font-weight: bold;
    text-align: right;
    color: #fff;
    background-color: #000; /* Black background */
    padding: 20px;
    border-radius: 12px; /* Smooth rounded corners */
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3); /* Subtle shadow for depth */
    letter-spacing: 2px; /* Slight letter spacing */
    width: fit-content;
    margin-left: auto;
    margin-right: 0;
}

/* Optional: Hover effect */
.profile-container:hover {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

/* Reset */
html {
  box-sizing: border-box;
}
*, *:before, *:after {
  box-sizing: inherit;
}

/* Body styling */
body {
  display: flex;
  min-height: auto;
  background: whitesmoke;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  font-size: 16px;
  font-weight: 700;
  justify-content: center;
  align-items: center;
  margin: 0;
}

/* Container styles */
.container {
  display: flex;
  flex-direction: column;
  width: 100%;
  /*max-width: 600px;*/
  padding: 20px;
}

/* Button container layout */
.button-container {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: center;
  margin-top: -30px;
}

/* Button styles */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 20px;
  /*margin: 10px;*/
  font-size: 14px;
  font-weight: bold;
  color: #fff;
  text-align: center;
  text-decoration: none;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.15);
  flex: 1 0 150px; /* Adjust width for responsive layout */
}
.button-icon {
    width: 20px; /* Adjust size as needed */
    height: 20px;
    margin-right: 8px; /* Spacing between icon and text */
    vertical-align: middle;
}

/* Button specific colors */
.button.-gray {
  background-color: gray;
}

.button.-dark {
  background-color: #161616;
}

.button.-green {
  background-color: #3dd28d;
}

.button.-blue {
  background-color: #416dea;
}

/* Button hover effects */
.button:hover {
  opacity: 0.85;
  transform: translateY(-2px);
  color: #fff;
  text-decoration: none;
}

.button:active {
  opacity: 0.75;
  transform: translateY(0);
}

.button.-dark {
  background: linear-gradient(135deg, #000, #777777); /* Blue to green gradient */
}

.button.-dark:hover {
  background: linear-gradient(135deg, #777, #000); /* Darker blue to green on hover */
}

.button.-blue {
  background: linear-gradient(135deg, #416dea, #000); /* Blue to green gradient */
}

.button.-blue:hover {
  background: linear-gradient(135deg, #000, #416dea); /* Darker blue to green on hover */
}
.button.-green {
  background: linear-gradient(180deg, #3dd28d, #000); /* Blue to green gradient */
}

.button.-green:hover {
  background: linear-gradient(180deg, #000, #3dd28d); /* Darker blue to green on hover */
}
/* Responsive adjustments */
@media (max-width: 768px) {
  .button-container {
    gap: 15px;
  }
  .button {
    flex: 1 0 100%;
  }
}
